import{_ as d,C as o,o as r,c as l,a2 as a,E as i}from"./chunks/framework.kOe0DhAP.js";const f=JSON.parse('{"title":"系统架构","description":"现货链由委托、撮合、账户和行情共同完成。","frontmatter":{"title":"系统架构","description":"现货链由委托、撮合、账户和行情共同完成。"},"headers":[],"relativePath":"06/0602/060002.md","filePath":"06/0602/060002.md"}'),s={name:"06/0602/060002.md"};function n(c,t,_,h,p,m){const e=o("Flow");return r(),l("div",null,[t[0]||(t[0]=a('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h1><div class="doc-lead">现货链由委托、撮合、账户和行情共同完成。</div><h2 id="modules" tabindex="-1">模块划分与职责 <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;模块划分与职责 {#modules}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>主要职责</th><th>阅读时抓住什么</th></tr></thead><tbody><tr><td>coinex-entrust</td><td>委托相关业务与查询</td><td>订单受理、规则校验、委托查询入口</td></tr><tr><td>coinex-match</td><td>订单簿、撮合事件及相关账户运行态处理</td><td>谁持有未成交意图、何时产生成交</td></tr><tr><td>coinex-account</td><td>业务账户与账务相关服务</td><td>可用/冻结口径与资金变动记录</td></tr><tr><td>coinex-market</td><td>行情相关处理</td><td>深度、最新价、K 线等展示数据</td></tr><tr><td>用户与商户服务</td><td>身份、交易产品和商户上下文</td><td>谁能交易、交易哪个产品</td></tr></tbody></table><p>现货链路不等于「一个服务包办一切」。委托服务负责把交易意图变成可追踪订单；撮合服务维护订单簿并产出成交；账户侧保证资产变化可解释；行情侧把结果变成用户可见的盘口与曲线。功能全景中现货一行也对应委托与撮合，行情能力由 <code>coinex-market</code> 补充，详见<a href="/00/0002/000002">功能全景</a>。</p><h2 id="dataflow" tabindex="-1">模块交互与数据流向 <a class="header-anchor" href="#dataflow" aria-label="Permalink to &quot;模块交互与数据流向 {#dataflow}&quot;">​</a></h2>',7)),i(e,{steps:["用户提交交易意图","委托与规则检查","账户资金占用","撮合处理","订单 / 资产 / 行情更新"]}),t[1]||(t[1]=a('<p>图示描述业务逻辑先后关系，不保证每一步是独立远程调用或同一数据库事务。已检查的撮合服务本身也包含账户缓存和资产变动相关处理，因此不能机械理解为：冻结一定只发生在账户服务、结算一定只发生在另一个服务。</p><p>阅读数据流时建议追问四个问题：</p><ol><li>谁接受订单并给出可查询的业务编号？</li><li>谁决定这笔单能否进入订单簿？</li><li>谁在成交后改写订单剩余量与资产？</li><li>谁把深度、最新成交推给客户端？</li></ol><p>未完成委托的查询、初始化撮合事件与本地恢复边界，属于存储与恢复设计，详见<a href="/02/0203/020003">数据存储与缓存</a>。本页只说明现货链路职责，不把恢复实现写成已完成生产审计。</p><h2 id="facts" tabindex="-1">工程事实 <a class="header-anchor" href="#facts" aria-label="Permalink to &quot;工程事实 {#facts}&quot;">​</a></h2><p>以下内容来自工程检查，属于可观察事实，不是流程图上的推断：</p><ul><li>现货撮合可见红黑树订单簿、买卖价格队列、Disruptor 事件处理与初始化撮合事件。</li><li>委托类型枚举包含限价与市价。</li><li>委托状态包含未成交、部分成交、完全成交与已撤销。</li><li>撮合服务中存在账户缓存与资产变动相关处理，画模块图时不要假设「撮合只比价、账户只记账」的绝对切分。</li></ul><p>存储枚举值、内部队列名与服务间具体协议路径不在本手册展开；需要对接实现时，应回到工程与接口约定章节核对。</p>',8))])}const b=d(s,[["render",n]]);export{f as __pageData,b as default};
